        if (this.tin)
            this.fileList.push({ docId: this.TinId, fileType: 'tin', attachedfile: this.tin });
        if (this.cv)
            this.fileList.push({ docId: this.CVId, fileType: 'cv', attachedfile: this.cv });
        console.log("Final file list:", this.fileList);
