    convertOracleDateToInput(dateString) {
        if (!dateString)
            return '';
        const parts = dateString.split('-'); // ["08", "MAY", "25"]
        const day = +parts[0];
        const month = parts[1].toUpperCase();
        const shortYear = +parts[2];
        const monthMap = {
            JAN: 0, FEB: 1, MAR: 2, APR: 3, MAY: 4, JUN: 5,
            JUL: 6, AUG: 7, SEP: 8, OCT: 9, NOV: 10, DEC: 11
        };
        const fullYear = shortYear < 50 ? 2000 + shortYear : 1900 + shortYear;
        const jsDate = new Date(fullYear, monthMap[month], day);
        return Object(_angular_common__WEBPACK_IMPORTED_MODULE_2__["formatDate"])(jsDate, 'yyyy-MM-dd', 'en-US');
    }
